// Mídia da apresentação (Parte 1) — embutida como data URI porque
// o conector do GitHub só aceita texto.
// Prints REAIS das telas do sistema, capturados das auditorias da
// versão de teste (artefato sistema-do-garcom, 10–11/11/2026):
// mesas = grade de Mesas; pedido = Novo Pedido; resumo = Resumo do
// pedido; conta = via do balcão (conta fechada). Vídeo do hero: ambiente
// de restaurante gerado por IA (sem gente em close, sem texto),
// 5s em loop, 640x360, 15fps, comprimido. LANDING_HERO_POSTER é um
// quadro estático desse vídeo (2s, JPEG) para quando o aparelho
// pede movimento reduzido — o hero nunca fica sem imagem.

export const LANDING_PRINTS: { src: string; caption: string }[] = [
  { src: 'data:image/webp;base64,', caption: 'Grade de mesas ao vivo' },
  { src: 'data:image/webp;base64,', caption: 'Pedido no celular, com preço' },
  { src: 'data:image/webp;base64,', caption: 'Resumo antes de enviar' },
  { src: 'data:image/webp;base64,', caption: 'A conta sai no balcão' },
];

export const LANDING_HERO_VIDEO = 'data:video/mp4;base64,';

export const LANDING_HERO_POSTER = 'data:image/jpeg;base64,';

